function moduleCard(m,i){let cls=m.status==='草稿'?'draft':m.status==='审核中'?'review':'';return `<section class="card module-card" data-module-card data-name="${m.name}" data-status="${m.status}" style="--accent:${m.color};--tint:${m.tint}"><i class="module-accent"></i><div class="module-card-head"><span class="module-symbol">${m.symbol}</span><span class="status-pill ${cls}">${m.status}</span></div><h3>${m.name}</h3><p>${m.desc}</p><div class="module-stats"><span><strong>${m.units}</strong>内容单元</span><span><strong>${m.tasks}</strong>任务节点</span><span><strong>${m.version}</strong>当前版本</span><div class="module-actions"><button class="btn small" data-edit-module="${i}">进入编排</button><button class="icon-more" data-module-more="${i}">•••</button></div></div></section>`}

