function pageRow(p,i){let cls=p.status==='已发布'?'green':p.status==='草稿'?'orange':'';return `<tr class="row-click" data-page-row data-name="${p.name}" data-module="${p.module}" data-status="${p.status}" data-route="${p.route}"><td><i class="checkbox" data-row-check></i></td><td><div class="page-title-cell"><span class="page-cover" style="--from:${p.color[0]};--to:${p.color[1]}">${p.name.slice(0,1)}</span><div><strong>${p.name}</strong><small>${p.id}</small></div></div></td><td>${p.module}</td><td><code class="route-code">${p.route}</code></td><td>${p.template}</td><td>${p.components}</td><td><span class="tiny-tag ${cls}">${p.status}</span></td><td>${p.owner}<br><small style="color:#9aa4b3">${p.updated}</small></td><td><button class="table-action" data-page-edit="${i}">装修</button><button class="table-action" data-page-more="${i}">更多</button></td></tr>`}

