function navigate(page){
  document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===page));
  breadcrumb.textContent=pageNames[page];
  if(page==='dashboard')renderDashboard();else if(page==='modules')renderModules();else if(page==='pages')renderPages();else if(page==='pageEditor')renderPageBuilder();else if(page==='composer')renderComposer();else if(page==='voices')renderVoices();else if(page==='questions')renderQuestions();else if(page==='releases')renderReleases();else renderPlaceholder(page);
  document.querySelector('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});
}

function openModal(content,wide=false){modal.className=`modal${wide?' wide':''}`;modal.innerHTML=content;modalBackdrop.classList.add('open');modalBackdrop.setAttribute('aria-hidden','false')}
function closeModal(){modalBackdrop.classList.remove('open');modalBackdrop.setAttribute('aria-hidden','true')}
function toast(title,detail){let el=document.createElement('div');el.className='toast';el.innerHTML=`<i>✓</i><div><strong>${title}</strong><p>${detail}</p></div>`;document.querySelector('#toastStack').append(el);setTimeout(()=>el.remove(),3600)}

function importModal(step=1){
  const steps=`<div class="stepper"><div class="step ${step>=1?'active':''} ${step>1?'done':''}"><i>${step>1?'✓':'1'}</i>上传文件</div><span class="step-line"></span><div class="step ${step>=2?'active':''} ${step>2?'done':''}"><i>${step>2?'✓':'2'}</i>数据校验</div><span class="step-line"></span><div class="step ${step>=3?'active':''}"><i>3</i>确认导入</div></div>`;
  let body='';let foot='';
  if(step===1){body=`${steps}<div class="dropzone"><div><span class="upload-icon">⇧</span><strong>拖拽 XLSX 或 ZIP 文件到这里</strong><p>支持题目、选项、答案、解析及图片资源；单次最多 5,000 道题</p><button class="btn small" id="chooseSample">选择文件</button></div></div><div class="template-tip"><span>ⓘ</span><span>首次导入请使用标准字段模板，避免校验失败</span><button>下载导入模板.xlsx</button></div>`;foot=`<button class="btn" data-close>取消</button><button class="btn primary" id="nextImport">下一步：开始校验</button>`}
  if(step===2){body=`${steps}<div class="file-row"><span class="file-symbol">XLSX</span><div><strong>健康卫生专项题库_0922.xlsx</strong><small>1.8 MB · 240 条数据 · 12 张图片</small></div><span class="ok">✓ 上传完成</span></div><div class="check-summary"><div class="check-box"><span>数据总数</span><strong>240</strong></div><div class="check-box"><span>校验通过</span><strong>238</strong></div><div class="check-box warn"><span>警告</span><strong>3</strong></div><div class="check-box error"><span>错误</span><strong>2</strong></div></div><div class="error-list"><div class="error-row"><b>第 26 行</b><span>正确答案未匹配到选项编码</span><em>必须修正</em></div><div class="error-row"><b>第 138 行</b><span>题目编号 Q-3741 已存在</span><em>必须修正</em></div><div class="error-row"><b style="color:#cb8739">第 82 行</b><span>题目解析为空，可导入后补充</span><em>警告</em></div></div>`;foot=`<button class="btn" id="backImport">上一步</button><button class="btn" id="exportErrors">导出错误明细</button><button class="btn primary" id="confirmImport">忽略警告，导入 238 条</button>`}
  if(step===3){body=`${steps}<div style="text-align:center;padding:18px 20px 25px"><div class="upload-icon" style="background:#e9f8f3;color:#2eaa7e">✓</div><h3 style="margin:12px 0 7px;font-size:16px">题库导入完成</h3><p style="color:#8490a3;font-size:11px;line-height:1.7">成功导入 238 条，失败 2 条。系统已生成批次记录<br>IMP-20260922-04，可在 24 小时内整批回滚。</p></div><div class="check-summary"><div class="check-box"><span>新增题目</span><strong>226</strong></div><div class="check-box"><span>更新题目</span><strong>12</strong></div><div class="check-box"><span>失败</span><strong style="color:#df5560">2</strong></div><div class="check-box"><span>耗时</span><strong>18s</strong></div></div>`;foot=`<button class="btn" id="downloadReport">下载导入报告</button><button class="btn primary" data-close>完成</button>`}
  openModal(`<div class="modal-head"><h2>批量导入题库</h2><button class="modal-close" data-close>×</button></div><div class="modal-body">${body}</div><div class="modal-foot">${foot}</div>`);
}

function resourceModal(){openModal(`<div class="modal-head"><h2>添加内容任务</h2><button class="modal-close" data-close>×</button></div><div class="modal-body"><div class="resource-tabs"><button class="active">视频资源</button><button>游戏实例</button><button>音频</button><button>图文</button></div><div style="display:flex;gap:9px;margin-bottom:13px"><input class="search" style="flex:1;width:auto" placeholder="搜索资源名称"><select class="select"><option>全部标签</option><option>健康卫生</option></select></div><div class="resource-grid">${resource('眼睛的秘密','科普视频 · 03:28','#e5f2ff','#3772d8',true)}${resource('护眼操一起做','跟练视频 · 02:10','#fff1e6','#da863b')}${resource('户外活动好处多','动画视频 · 04:06','#eaf8f2','#299c76')}${resource('正确的阅读姿势','示范视频 · 01:45','#f0edff','#7061d1')}${resource('光线与眼睛','科普视频 · 03:12','#fff0f3','#d7667e')}${resource('眼睛休息一下','儿歌视频 · 02:46','#edf6e9','#719136')}</div></div><div class="modal-foot"><span style="margin-right:auto;color:#8b96a7;font-size:10px">已选择 1 项</span><button class="btn" data-close>取消</button><button class="btn primary" id="addResource">添加到任务路径</button></div>`,true)}
