function editQuestionModal(){openModal(`<div class="modal-head"><h2>编辑题目 Q-3862</h2><button class="modal-close" data-close>×</button></div><div class="modal-body"><div class="field"><label>题目内容</label><textarea style="height:72px">看书时，眼睛离书本多远比较合适？</textarea></div><div class="field-row"><div class="field"><label>题型</label><select><option>单选题</option><option>判断题</option><option>多选题</option></select></div><div class="field"><label>难度</label><select><option>简单</option><option>中等</option><option>困难</option></select></div></div><div class="field"><label>选项</label><input value="A. 约一尺　 B. 越近越好　 C. 没有要求"></div><div class="field"><label>正确答案</label><input value="A"></div><div class="field"><label>答案解析</label><textarea>阅读时保持约一尺距离，有助于减少眼睛疲劳。</textarea></div></div><div class="modal-foot"><button class="btn" data-close>取消</button><button class="btn primary" id="saveQuestion">保存题目</button></div>`)}

function filterPages(){let keyword=(document.querySelector('#pageSearch')?.value||'').trim().toLowerCase();let module=document.querySelector('#pageModule')?.value||'';let status=document.querySelector('#pageStatus')?.value||'';let visible=0;document.querySelectorAll('[data-page-row]').forEach(row=>{let ok=(!keyword||(row.dataset.name+row.dataset.route).toLowerCase().includes(keyword))&&(!module||row.dataset.module===module)&&(!status||row.dataset.status===status);row.style.display=ok?'':'none';if(ok)visible++});let count=document.querySelector('#pageCount');if(count)count.textContent=`共 36 个二级页面 · 当前展示 ${visible} 个`}
function filterModules(){let keyword=(document.querySelector('#moduleSearch')?.value||'').trim().toLowerCase();let status=document.querySelector('#moduleStatus')?.value||'';let visible=0;document.querySelectorAll('[data-module-card]').forEach(card=>{let ok=(!keyword||card.dataset.name.toLowerCase().includes(keyword))&&(!status||card.dataset.status===status);card.style.display=ok?'':'none';if(ok)visible++});let count=document.querySelector('#moduleCount');if(count)count.textContent=`共 ${visible} 个模块`}
function selectBuilderBlock(type){document.querySelectorAll('.canvas-block').forEach(x=>x.classList.toggle('selected',x.dataset.canvas===type));document.querySelectorAll('.builder-tree [data-component]').forEach(x=>x.classList.toggle('active',x.dataset.component===type));let names={banner:'顶部主题区',categories:'分类导航',tasks:'推荐任务',list:'内容列表',game:'游戏推荐',video:'视频推荐',campaign:'运营活动'};let title=document.querySelector('#inspectorTitle');if(title)title.textContent=names[type]||'组件属性'}

document.addEventListener('click',e=>{
  const nav=e.target.closest('.nav-item');if(nav){navigate(nav.dataset.page);return}
  const go=e.target.closest('[data-go]');if(go){navigate(go.dataset.go);return}
  if(e.target.closest('[data-page-edit]')){navigate('pageEditor');return}
  const pageRowEl=e.target.closest('[data-page-row]');if(pageRowEl&&!e.target.closest('button')&&!e.target.closest('.checkbox')){document.querySelectorAll('[data-page-row]').forEach(x=>x.classList.remove('selected-row'));pageRowEl.classList.add('selected-row');toast('已选择页面',`${pageRowEl.dataset.module} · ${pageRowEl.dataset.name}`);return}
  if(e.target.id==='newPage'){newPageModal();return}
  if(e.target.id==='createPageConfirm'){let name=document.querySelector('#newPageName')?.value.trim();if(!name){toast('请填写页面名称','页面名称不能为空');return}closeModal();toast('二级页面创建成功',`${name} 已创建，正在进入页面装修`);setTimeout(()=>navigate('pageEditor'),450);return}
  if(e.target.id==='copyPage'){toast('页面已复制','已复制“健康卫生”并生成草稿副本');return}
  if(e.target.id==='pageSort'){document.querySelector('#pageTableBody')?.append(...[...document.querySelectorAll('[data-page-row]')].reverse());toast('已进入排序模式','当前页面顺序已反转，用于演示排序效果');return}
  if(e.target.closest('[data-page-more]')){openModal(`<div class="modal-head"><h2>页面操作</h2><button class="modal-close" data-close>×</button></div><div class="modal-body"><div class="activity-list" style="margin-top:0">${activity('⧉','复制为新页面','保留当前布局与内容关联','执行')}${activity('↗','查看线上页面','打开当前发布版本','预览')}${activity('◷','查看版本记录','比较历史版本并回滚','查看')}</div></div><div class="modal-foot"><button class="btn danger" id="archivePage">停用页面</button><button class="btn" data-close>关闭</button></div>`);return}
  if(e.target.id==='archivePage'){closeModal();toast('页面已停用','原路由将保留，前端不再展示该页面');return}
  const rowCheck=e.target.closest('[data-row-check]');if(rowCheck){rowCheck.classList.toggle('checked');rowCheck.closest('tr')?.classList.toggle('selected-row',rowCheck.classList.contains('checked'));return}
  const checkAll=e.target.closest('[data-check-all]');if(checkAll){checkAll.classList.toggle('checked');document.querySelectorAll('[data-row-check]').forEach(x=>x.classList.toggle('checked',checkAll.classList.contains('checked')));return}
  if(e.target.closest('[data-edit-module]')){navigate('composer');return}
  if(e.target.closest('[data-module-more]')){toast('模块操作菜单','可复制模块、调整状态或查看版本记录');return}
  if(e.target.id==='mobileMenu'){document.querySelector('#sidebar').classList.toggle('open');return}
  if(e.target.id==='importQuestions'){importModal(1);return}
  if(e.target.id==='nextImport'||e.target.id==='chooseSample'){importModal(2);return}
  if(e.target.id==='backImport'){importModal(1);return}
  if(e.target.id==='confirmImport'){importModal(3);return}
  if(e.target.id==='addTask'){resourceModal();return}
  const resourceTab=e.target.closest('.resource-tabs button');if(resourceTab){resourceTab.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===resourceTab));toast('资源类型已切换',`当前浏览：${resourceTab.textContent}`);return}
  const resourceCard=e.target.closest('.resource-card');if(resourceCard){resourceCard.classList.toggle('selected');let existing=resourceCard.querySelector('.resource-check');if(existing)existing.remove();else resourceCard.insertAdjacentHTML('afterbegin','<span class="resource-check">✓</span>');let count=document.querySelectorAll('.resource-card.selected').length;let label=modal.querySelector('.modal-foot span');if(label)label.textContent=`已选择 ${count} 项`;return}
  if(e.target.id==='addResource'){closeModal();toast('任务已添加','“眼睛的秘密”已加入保护眼睛任务路径末尾');return}
  const chain=e.target.closest('.chain-item');if(chain&&!e.target.closest('button')){document.querySelectorAll('.chain-item').forEach(x=>x.classList.remove('selected'));chain.classList.add('selected');let title=chain.querySelector('h4')?.textContent.replace(/视频|游戏/,'').trim();let small=document.querySelector('.inspector .panel-head small');if(small&&title)small.textContent=`当前：${title.replace(/^\d+\.\s*/,'')}`;return}
  const tree=e.target.closest('.tree-row');if(tree&&tree.closest('.tree')){tree.closest('.tree').querySelectorAll('.tree-row').forEach(x=>x.classList.remove('active'));tree.classList.add('active');toast('内容节点已切换',tree.textContent.replace(/\d+$/,'').trim());return}
  const componentTree=e.target.closest('[data-component]');if(componentTree){selectBuilderBlock(componentTree.dataset.component);return}
  const canvas=e.target.closest('[data-canvas]');if(canvas){selectBuilderBlock(canvas.dataset.canvas);return}
  const addComponent=e.target.closest('[data-add-component]');if(addComponent){let type=addComponent.dataset.addComponent;toast('组件已添加',`${addComponent.textContent.trim()}已添加到页面底部`);selectBuilderBlock(type);return}
  const device=e.target.closest('[data-device]');if(device){device.parentElement.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===device));let preview=document.querySelector('#devicePreview');if(preview)preview.style.width=device.dataset.device==='tv'?'min(760px,100%)':device.dataset.device==='tablet'?'min(640px,100%)':'min(380px,100%)';toast('预览设备已切换',device.textContent.trim());return}
  const inspectorTab=e.target.closest('[data-inspector-tab]');if(inspectorTab){document.querySelectorAll('[data-inspector-tab]').forEach(x=>x.classList.toggle('active',x===inspectorTab));document.querySelectorAll('[data-inspector-pane]').forEach(x=>x.classList.toggle('active',x.dataset.inspectorPane===inspectorTab.dataset.inspectorTab));return}
  const templateDemo=e.target.closest('[data-template-demo]');if(templateDemo){templateDemo.parentElement.querySelectorAll('.template-mini').forEach(x=>x.classList.toggle('active',x===templateDemo));let preview=document.querySelector('#devicePreview');if(preview)preview.dataset.templateMode=templateDemo.dataset.templateDemo;let map={hub:'主题入口页',carousel:'横向轮播页',path:'路径关卡页',hotspot:'场景热点页',media:'视频任务页',detail:'知识详情页'};let sub=document.querySelector('.page-heading p');if(sub)sub.textContent=`快乐成长 / 健康卫生 · 模板：${map[templateDemo.dataset.templateDemo]} · 自动保存于刚刚`;toast('页面模板已切换',`${map[templateDemo.dataset.templateDemo]}预览已加载`);return}
  const speak=e.target.closest('[data-speak]');if(speak){speakText(speak.dataset.speak);return}
  const speakSource=e.target.closest('[data-speak-source]');if(speakSource){speakText(document.querySelector(`#${speakSource.dataset.speakSource}`)?.value||'');return}
  if(e.target.id==='focusRules'){openModal(`<div class="modal-head"><h2>焦点与遥控器规则</h2><button class="modal-close" data-close>×</button></div><div class="modal-body"><div class="focus-rule-map"><div><b>默认焦点</b><span>保护眼睛</span></div><div><b>← / →</b><span>同组循环切换卡片</span></div><div><b>↑ / ↓</b><span>切换主题区与任务区</span></div><div><b>确认键</b><span>进入详情或开始任务</span></div><div><b>返回键</b><span>返回上一级并记忆焦点</span></div></div><div class="template-tip"><span>ⓘ</span><span>焦点变化时自动播报名称、状态和动态进度，锁定项播报解锁条件。</span></div></div><div class="modal-foot"><button class="btn" data-close>取消</button><button class="btn primary" id="saveFocusRules">保存规则</button></div>`);return}
  if(e.target.id==='saveFocusRules'){closeModal();toast('焦点规则已保存','遥控器方向映射和语音播报规则已更新');return}
  if(e.target.id==='validatePage'){toast('页面校验通过','结构、素材、旁白、焦点路径与解锁规则共 18 项全部通过');return}
  if(e.target.id==='newVoice'){newVoiceModal();return}
  if(e.target.closest('[data-edit-voice]')){newVoiceModal(e.target.closest('[data-voice-row]')?.dataset.text||'');return}
  if(e.target.id==='saveVoice'){closeModal();toast('旁白已保存','已加入待审核列表，可绑定页面或焦点元素');return}
  if(e.target.id==='voiceExport'){toast('旁白脚本已导出','正在生成 XLSX 文件');return}
  if(e.target.id==='voiceImport'){toast('批量导入已就绪','支持 XLSX 脚本和 ZIP 音频包');return}
  const toggle=e.target.closest('[data-toggle]');if(toggle){toggle.classList.toggle('on');return}
  const radio=e.target.closest('.radio-card');if(radio){radio.parentElement.querySelectorAll('.radio-card').forEach(x=>x.classList.toggle('active',x===radio));return}
  if(e.target.id==='applyComponent'){let title=document.querySelector('#heroTitleInput')?.value;let desc=document.querySelector('#heroDescInput')?.value;let hero=document.querySelector('.hero-block');if(hero){hero.querySelector('h3').textContent=title||'未命名主题';hero.querySelector('p').textContent=desc||''}toast('组件设置已应用','页面预览已同步更新');return}
  if(e.target.id==='savePage'){toast('页面已保存并提交审核','健康卫生页面已生成新版本 P-1001-V8');return}
  if(e.target.id==='previewPage'){toast('已打开交互预览','可在手机或平板模式查看页面效果');return}
  if(e.target.id==='deleteComponent'){let selected=document.querySelector('.canvas-block.selected');if(selected){selected.style.display='none';toast('组件已从页面移除','保存前可以使用撤销恢复')};return}
  if(['undoAction','redoAction','toggleGrid','refreshPreview'].includes(e.target.id)){toast('画布操作已执行',e.target.textContent.trim());return}
  if(e.target.closest('[data-close]')){closeModal();return}
  if(e.target.id==='saveDraft'){toast('草稿已保存','所有内容变更已保存，尚未影响线上版本');return}
  if(e.target.id==='submitReview'){toast('已提交审核','版本 V2.4 的内容变更已进入审核队列');return}
  if(e.target.id==='exportQuestions'){toast('导出任务已创建','正在生成 XLSX 文件，完成后将自动下载');return}
  if(e.target.id==='exportErrors'||e.target.id==='downloadReport'){toast('文件已生成','演示原型：下载任务创建成功');return}
  if(e.target.id==='validateRelease'){toast('上线校验通过','12 项必检规则全部通过，可以安全发布');e.target.textContent='✓ 12/12 校验通过';return}
  if(e.target.id==='publishRelease'){openModal(`<div class="modal-head"><h2>确认发布 V2.4</h2><button class="modal-close" data-close>×</button></div><div class="modal-body"><div class="template-tip" style="margin-top:0;background:#fff5e8;color:#875b28"><span>!</span><span>发布后将影响约 12,480 名用户。系统会保留 V2.3 作为可回滚版本。</span></div><div style="padding:18px 0 3px;font-size:12px;line-height:2;color:#536075"><b>变更范围：</b>4 个模块、18 项内容、240 道题目<br><b>发布时间：</b>立即发布<br><b>回滚策略：</b>异常时一键回滚至 V2.3</div></div><div class="modal-foot"><button class="btn" data-close>取消</button><button class="btn primary" id="confirmPublish">确认并发布</button></div>`);return}
  if(e.target.id==='confirmPublish'){closeModal();toast('版本发布任务已开始','V2.4 正在发布，预计 1—2 分钟完成');return}
  if(e.target.id==='previewModule'){toast('已生成预览','前端预览链接有效期为 2 小时');return}
  if(e.target.id==='addModule'||e.target.id==='createRelease'){toast('已进入创建流程','演示原型已保留完整创建入口');return}
  if(e.target.classList.contains('table-action')&&e.target.textContent.trim()==='编辑'){editQuestionModal();return}
  if(e.target.id==='saveQuestion'){closeModal();toast('题目已保存','Q-3862 的修改已加入待发布版本');return}
  if(e.target.closest('.pages button')){let button=e.target.closest('button');button.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));if(!['‹','›','…'].includes(button.textContent.trim()))button.classList.add('active');toast('列表已翻页',`当前页：${button.textContent.trim()}`);return}
  if(e.target.closest('.btn,.icon-more,.text-link,.table-action')){toast('交互已响应','此操作在原型中已进入对应流程');return}
});
document.addEventListener('input',e=>{if(e.target.id==='pageSearch')filterPages();if(e.target.id==='moduleSearch')filterModules();if(e.target.id==='heroTitleInput'){let h=document.querySelector('.hero-block h3');if(h)h.textContent=e.target.value}if(e.target.id==='heroDescInput'){let p=document.querySelector('.hero-block p');if(p)p.textContent=e.target.value}});
document.addEventListener('change',e=>{if(e.target.id==='pageModule'||e.target.id==='pageStatus')filterPages();if(e.target.id==='moduleStatus')filterModules();if(e.target.id==='previewState'){let preview=document.querySelector('#devicePreview');if(preview){preview.classList.remove('state-progress','state-new','state-done','state-locked');preview.classList.add(`state-${e.target.value}`)}let labels={progress:['进行中 1/10','已完成','未开始'],new:['未开始','未开始','未开始'],done:['已完成 10/10','已完成','已完成'],locked:['已锁定','已锁定','已锁定']};document.querySelectorAll('.category-tile small').forEach((x,i)=>x.textContent=labels[e.target.value][i]||labels[e.target.value][0]);toast('用户状态已切换',e.target.options[e.target.selectedIndex].text)}});
modalBackdrop.addEventListener('click',e=>{if(e.target===modalBackdrop)closeModal()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();let cards=[...document.querySelectorAll('.category-tile')];if(cards.length&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();let current=Math.max(0,cards.indexOf(document.activeElement));let next=e.key==='ArrowRight'?(current+1)%cards.length:(current-1+cards.length)%cards.length;cards[next].focus();speakText(cards[next].dataset.speak)}if(e.key==='Enter'&&document.activeElement?.classList.contains('category-tile'))speakText(document.activeElement.dataset.speak)});
navigate('dashboard');
